namespace TemplateF
{
    internal class SolutionF
    {
        private readonly StreamReader sr = new(Console.OpenStandardInput());
        private T Read<T>()
            where T : struct, IConvertible
        {
            char c;
            dynamic res = default(T);
            dynamic sign = 1;
            while (!sr.EndOfStream && char.IsWhiteSpace((char)sr.Peek())) sr.Read();
            if (!sr.EndOfStream && (char)sr.Peek() == '-')
            {
                sr.Read();
                sign = -1;
            }
            while (!sr.EndOfStream && char.IsDigit((char)sr.Peek()))
            {
                c = (char)sr.Read();
                res = res * 10 + c - '0';
            }
            return res * sign;
        }

        private T[] ReadArray<T>(int n)
            where T : struct, IConvertible
        {
            T[] arr = new T[n];
            for (int i = 0; i < n; ++i) arr[i] = Read<T>();
            return arr;
        }

        public void Solve()
        {
            StringBuilder output = new();
            const int maxk = 100000, mod = 998244353, bw = 20;
            List<int>[] d = new List<int>[maxk + 1];
            for (int i = 1; i <= maxk; ++i) d[i] = new() { 1 };
            for (int i = 2; i <= maxk; ++i) {
                for (int j = i; j <= maxk; j += i) d[j].Add(i);
            }
            int[,] dp = new int[bw + 1, maxk + 1], S = new int[bw + 1, maxk + 1];
            for (int k = 1; k <= maxk; ++k) dp[1, k] = S[1, k] = 1;
            for (int i = 2; i <= bw; ++i) {
                for (int j = 1; j <= maxk; ++j) {
                    foreach (var k in d[j]) {
                        dp[i, j] += dp[i - 1, k];
                        dp[i, j] %= mod;
                    }
                    S[i, j] = (S[i - 1, j] + dp[i, j]) % mod;
                }
            }
            int T = Read<int>();
            while (T-- > 0)
            {
                int k = Read<int>(), n = Read<int>();
                if (n <= bw) {
                    for (int j = 1; j <= k; ++j) output.Append(S[n, j]).Append(' ');
                } else {
                    int _k = k;
                    for (k = 1; k <= _k; ++k)  {
                        long ans = 0;
                        for (int i = 1; i <= bw; ++i) {
                            long t = S[i, k];
                            for (int j = 1; j <= bw; ++j) {
                                if (j == i) continue;
                                t *= n - j;
                                t %= mod;
                                t *= Inv((mod + i - j) % mod, mod);
                                t %= mod;
                            }
                            ans = (ans + t) % mod;
                        }
                        output.Append(ans).Append(' ');
                    }
                }
                output.AppendLine();
            }
            Console.Write(output.ToString());
        }
        public static long Inv(long a, long Mod) {
            long u = 0, v = 1, m = Mod;
            while (a > 0) {
                long t = m / a;
                m -= t * a; (a, m) = (m, a);
                u -= t * v; (u, v) = (v, u);
            }
            return (u % Mod + Mod) % Mod;
        }
    }
}

